# Self-evaluation on N=8 pilot - load from per-judge subdirs
import json, os
import numpy as np
from collections import defaultdict

judge_dir = 'exp001/results'
records = []

for jname in os.listdir(judge_dir):
    jpath = os.path.join(judge_dir, jname)
    if not os.path.isdir(jpath):
        continue
    if jname.endswith('_n17'):
        continue  # Skip n17 data
    for f in os.listdir(jpath):
        if f.endswith('.jsonl'):
            with open(os.path.join(jpath, f)) as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    rec = json.loads(line)
                    if rec.get('status') == 'ok':
                        records.append(rec)

print(f'Total N=8 records: {len(records)}')

# Check models and judges
models = set(r['model_a'] for r in records)
judges = set(r['judge'] for r in records)
print(f'Models: {sorted(models)}')
print(f'Judges: {sorted(judges)}')

# Average AB/BA and compute self-eval
grouped = defaultdict(list)
for r in records:
    key = (r['model_a'], r['item_id'], r['judge'])
    grouped[key].append(float(r['score']))

# Self-evaluation for qwen2.5-72b and llama-3.3-70b
# Map model names in N=8 data
self_pairs = []
for m in sorted(models):
    for j in sorted(judges):
        if 'qwen2.5-72b' in m.lower() and 'qwen2.5-72b' in j.lower():
            self_pairs.append((m, j))
        if 'llama-3.3-70b' in m.lower() and 'llama-3.3-70b' in j.lower():
            self_pairs.append((m, j))

print(f'\nSelf-judge pairs found: {self_pairs}')

for model_name, judge_name in self_pairs:
    # Count items (after tie dropping)
    self_items = {}
    for (m, i, j), scores in grouped.items():
        if m == model_name and j == judge_name:
            avg = np.mean(scores)
            if abs(avg - 0.5) < 1e-9:
                continue
            self_items[i] = 1 if avg > 0.5 else 0

    n_total = len(self_items)
    n_wins = int(sum(self_items.values()))

    # Cross-judge
    cross_per_judge = defaultdict(lambda: [0, 0])
    for (m, i, j), scores in grouped.items():
        if m == model_name and j != judge_name:
            avg = np.mean(scores)
            if abs(avg - 0.5) < 1e-9:
                continue
            cross_per_judge[j][1] += 1
            if avg > 0.5:
                cross_per_judge[j][0] += 1

    per_judge_rates = [w/t for j, (w, t) in cross_per_judge.items() if t > 0]
    mean_cross = np.mean(per_judge_rates) if per_judge_rates else 0

    print(f'\n{model_name}:')
    print(f'  Self-judging ({judge_name}): {n_wins}/{n_total} = {n_wins/n_total:.3f}' if n_total > 0 else f'  Self-judging: no data')
    print(f'  Cross-judge mean: {mean_cross:.3f}')
    for j in sorted(cross_per_judge.keys()):
        w, t = cross_per_judge[j]
        print(f'    {j}: {w}/{t} = {w/t:.3f}')
